int main() {
    int len = 60000 * 1024;
    unsigned char *pt = malloc(len);
    unsigned char *ct = malloc(len + 16);
    unsigned char key[16] = {0};
    unsigned char nonce[12] = {0};
    unsigned char aad[32] = {0};

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    struct timeval t0, t1;
    gettimeofday(&t0, NULL);

    for (int i = 0; i < 30; i++) {
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);

        int outl;
        EVP_EncryptUpdate(ctx, NULL, &outl, aad, 32);
        EVP_EncryptUpdate(ctx, ct, &outl, pt, len);

        int out_len = outl;
        EVP_EncryptFinal_ex(ctx, ct + out_len, &outl);
        out_len += outl;

        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, ct + out_len);
    }

    gettimeofday(&t1, NULL);
    double elapsed = (t1.tv_sec - t0.tv_sec) + (t1.tv_usec - t0.tv_usec) / 1000000.0;
